-- 任务NPC任务标记补齐
UPDATE creature_template SET NpcFlags = NpcFlags | 2 WHERE Entry IN (
    SELECT DISTINCT id FROM creature_questrelation WHERE quest BETWEEN 90100 AND 90211
    UNION
    SELECT DISTINCT id FROM creature_involvedrelation WHERE quest BETWEEN 90100 AND 90211
);

-- ============================================================
-- 最终调整：等级/经验/金币/装备方案
-- 1) 前3步为30级任务、不给经验；实战训练30级可接，
--    一次性给足 30->60 的经验（300万，RewMoneyMaxLevel=1800000）；
-- 2) 战争物资（发徽记）顺带发放60级附近战场装备 + 职业武器
--    （武器由实战训练挪至此处）。
-- ============================================================

UPDATE quest_template SET MinLevel = 30, QuestLevel = 30 WHERE Entry BETWEEN 90120 AND 90138;
UPDATE quest_template SET MinLevel = 30                  WHERE Entry BETWEEN 90140 AND 90158;

UPDATE quest_template SET RewMoneyMaxLevel = 0       WHERE Entry BETWEEN 90100 AND 90109;
UPDATE quest_template SET RewMoneyMaxLevel = 0       WHERE Entry IN (90110, 90111);
UPDATE quest_template SET RewMoneyMaxLevel = 0       WHERE Entry BETWEEN 90120 AND 90138;
UPDATE quest_template SET RewMoneyMaxLevel = 1800000 WHERE Entry BETWEEN 90140 AND 90158;
UPDATE quest_template SET RewMoneyMaxLevel = 0       WHERE Entry BETWEEN 90200 AND 90209;
UPDATE quest_template SET RewMoneyMaxLevel = 0       WHERE Entry IN (90210, 90211);

UPDATE quest_template SET RewOrReqMoney = 10000  WHERE Entry BETWEEN 90100 AND 90109;
UPDATE quest_template SET RewOrReqMoney = 10000  WHERE Entry IN (90110, 90111);
UPDATE quest_template SET RewOrReqMoney = 20000  WHERE Entry BETWEEN 90120 AND 90138;
UPDATE quest_template SET RewOrReqMoney = 40000  WHERE Entry BETWEEN 90140 AND 90158;
UPDATE quest_template SET RewOrReqMoney = 80000  WHERE Entry BETWEEN 90200 AND 90209;
UPDATE quest_template SET RewOrReqMoney = 100000 WHERE Entry IN (90210, 90211);

UPDATE quest_template SET
  RewItemId2 = 19084, RewItemCount2 = 1,
  RewItemId3 = 19522, RewItemCount3 = 1,
  RewItemId4 = 19097, RewItemCount4 = 1
WHERE Entry IN (90120, 90121, 90122, 90123, 90125, 90128);

UPDATE quest_template SET
  RewItemId2 = 19086, RewItemCount2 = 1,
  RewItemId3 = 19522, RewItemCount3 = 1,
  RewItemId4 = 19098, RewItemCount4 = 1
WHERE Entry IN (90124, 90126, 90127);

UPDATE quest_template SET
  RewItemId2 = 19083, RewItemCount2 = 1,
  RewItemId3 = 19109, RewItemCount3 = 1,
  RewItemId4 = 19095, RewItemCount4 = 1
WHERE Entry IN (90130, 90131, 90132, 90133, 90135, 90138);

UPDATE quest_template SET
  RewItemId2 = 19085, RewItemCount2 = 1,
  RewItemId3 = 19109, RewItemCount3 = 1,
  RewItemId4 = 19096, RewItemCount4 = 1
WHERE Entry IN (90134, 90136, 90137);

UPDATE quest_template SET
  RewChoiceItemId1 = CASE Entry
    WHEN 90120 THEN 17016 WHEN 90121 THEN 19104 WHEN 90122 THEN 19993 WHEN 90123 THEN 19099
    WHEN 90124 THEN 19101 WHEN 90125 THEN 19961 WHEN 90126 THEN 19102 WHEN 90127 THEN 20720
    WHEN 90128 THEN 24155
    WHEN 90130 THEN 17016 WHEN 90131 THEN 19104 WHEN 90132 THEN 19993 WHEN 90133 THEN 19099
    WHEN 90134 THEN 19101 WHEN 90135 THEN 19961 WHEN 90136 THEN 19102 WHEN 90137 THEN 20720
    WHEN 90138 THEN 24155
    ELSE RewChoiceItemId1
  END,
  RewChoiceItemCount1 = 1
WHERE Entry BETWEEN 90120 AND 90138;

UPDATE quest_template SET RewChoiceItemId1 = 0, RewChoiceItemCount1 = 0 WHERE Entry BETWEEN 90140 AND 90158;

UPDATE quest_template SET RewSpell = 33388, RewSpellCast = 33389 WHERE Entry BETWEEN 90100 AND 90109;

UPDATE quest_template SET RewSpell = 33391, RewSpellCast = 33392 WHERE Entry BETWEEN 90200 AND 90209;
-- ============================================================
-- 图标更新（追加在最后）：推荐信用信件图标，套装包裹用礼物图标
-- 推荐信 90020/90021 -> INV_Misc_Note_01 (displayid 7798)
-- 套装包裹 90010-90018 -> INV_Misc_Gift_05 (displayid 21375)
-- ============================================================

UPDATE item_template SET displayid = 7798  WHERE entry IN (90020, 90021);
UPDATE item_template SET displayid = 21375 WHERE entry BETWEEN 90010 AND 90018;